func (policy *ThrottlingPolicy_STATUS) AssignProperties_To_ThrottlingPolicy_STATUS(destination *storage.ThrottlingPolicy_STATUS) error {
	// Create a new property bag
	propertyBag := genruntime.NewPropertyBag()

	// MetricId
	if policy.MetricId != nil {
		metricId := string(*policy.MetricId)
		destination.MetricId = &metricId
	} else {
		destination.MetricId = nil
	}

	// Name
	destination.Name = genruntime.ClonePointerToString(policy.Name)

	// RateLimitThreshold
	destination.RateLimitThreshold = genruntime.ClonePointerToInt(policy.RateLimitThreshold)

	// Type
	if policy.Type != nil {
		typeVar := string(*policy.Type)
		destination.Type = &typeVar
	} else {
		destination.Type = nil
	}

	// Update the property bag
	if len(propertyBag) > 0 {
		destination.PropertyBag = propertyBag
	} else {
		destination.PropertyBag = nil
	}

	// No error
	return nil
}

